import React, { useState } from 'react';
import './assets/style/Register.css';
import inscriptionImage from './assets/images/maquette_desktrop/img1_inscription.png'; // Importe l'image
import './assets/Fonts/'

const Register = () => {
  const [name, setName] = useState('');
  const [username, setUsername] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [agreeTerms, setAgreeTerms] = useState(false);

  const handleSubmit = (e) => {
    e.preventDefault();
    // Ici, tu vas appeler l'API d'inscription plus tard
    console.log('Name:', name, 'Username:', username, 'Email:', email, 'Password:', password, 'Agree Terms:', agreeTerms);
  };

  return (
    <div className="register-container">
      <div className="register-image">
        <img src={inscriptionImage} alt="Inscription" />
      </div>
      <div className="register-box">
        <h2>Sign Up to Receipt Flow</h2>
        <form onSubmit={handleSubmit}>
          <input
            type="text"
            placeholder="Name"
            value={name}
            onChange={(e) => setName(e.target.value)}
          />
          <input
            type="text"
            placeholder="Username"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
          />
          <input
            type="email"
            placeholder="Email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
          />
          <input
            type="password"
            placeholder="6+ Characters "
            value={password}
            onChange={(e) => setPassword(e.target.value)}
          />
          <div className="terms">
            <input
              type="checkbox"
              id="agreeTerms"
              checked={agreeTerms}
              onChange={(e) => setAgreeTerms(e.target.checked)}
            />
            <label htmlFor="agreeTerms">
              I agree with ReceiptFlow's Terms of Service, Privacy Policy, and default Notification Settings
            </label>
          </div>
          <button type="submit" className="create-account-button">Create Account</button>
        </form>
      </div>
    </div>
  );
};

export default Register;
